describe('Notification Panel Slide In', () => {
  beforeEach(() => {
    cy.visit('/notifications');
  });

  it('should display notification panel sliding in from the top when a notification is received', () => {
    // Verify notification panel is not visible initially
    cy.get('[data-testid="notification-panel"]').should('not.exist');

    // Trigger notification event
    cy.intercept('POST', '/api/notifications/new').as('notificationRequest');
    cy.get('[data-testid="notification-button"]').click();

    // Wait for notification API call
    cy.wait('@notificationRequest');

    // Verify notification panel appears
    cy.get('[data-testid="notification-panel"]').should('be.visible');
    cy.get('[data-testid="notification-panel"]').should('have.class', 'slide-in');

    // Verify notification content is displayed
    cy.get('[data-testid="notification-title"]').should('contain', 'New Message');
    cy.get('[data-testid="notification-message"]').should('contain', 'You have a new message');

    // Verify notification panel is sliding in from the top
    cy.get('[data-testid="notification-panel"]').should('have.css', 'transform', 'translateY(-100%)');

    // Verify close button is visible
    cy.get('[data-testid="notification-close-btn"]').should('be.visible');
  });

  it('should close notification panel when close button is clicked', () => {
    // Trigger notification
    cy.intercept('POST', '/api/notifications/new').as('notificationRequest');
    cy.get('[data-testid="notification-button"]').click();
    cy.wait('@notificationRequest');

    // Verify notification panel appears
    cy.get('[data-testid="notification-panel"]').should('be.visible');

    // Verify close button is visible
    cy.get('[data-testid="notification-close-btn"]').should('be.visible');

    // Click close button
    cy.get('[data-testid="notification-close-btn"]').click();

    // Verify notification panel is hidden
    cy.get('[data-testid="notification-panel"]').should('not.exist');

    // Verify notification panel does not slide back in
    cy.get('[data-testid="notification-panel"]').should('not.have.css', 'transform');
  });
});
